import json, hashlib
base=Path('/home/jonny/projects/boardgame-rules/docs/quality/summary-qa/john-company-second-edition/2026-11-05-batch-002957/expanded-v13-complete-requested-scope/luna-iteration-02/grading-reader-b/block-05')
packet=json.loads((base/'packet.json').read_text())
entries={e['id']:e for e in packet['entries']}
grades=[]
def add(id,grade,reason,parts,guesses=None,issue=None):
    entry=entries[id]
    atoms=entry['requested_fact_scope_entry']['material_requested_facts']
    assert len(parts)==len(atoms),(id,len(parts),len(atoms))
    reader=entry['reader_b_entry']
    texts=[reader.get('answer','')]+reader.get('case_conclusions',[])+[x.get('quote','') for x in reader.get('evidence',[])]+[x.get('fact','') for x in reader.get('clause_ledger',[])]
    material=[]
    for atom,(status,quotes) in zip(atoms,parts):
        assert status in ('covered','omitted','contradicted')
        if status=='covered': assert quotes,(id,atom)
        for q in quotes: assert any(q in text for text in texts),(id,q)
        material.append({'requirement':atom,'status':status,'reader_quotes':quotes})
    grades.append({'id':id,'grade':grade,'reason':reason,'material_parts':material,'unsupported_guesses':guesses or [],'summary_issue_if_any':issue})
def C(q): return ('covered',[q])
def O(): return ('omitted',[])
def X(*q): return ('contradicted',list(q))
